class Animal:
    def __init__(self, name):
        self.name = name
    def hello(self):
        return f"Я {self.name}"

class Dog(Animal):
    pass

d = Dog("Шарик")
print(d.hello(), isinstance(d, Animal), issubclass(Dog, Animal))

class Animal:
    def __init__(self, name):
        self.name = name
    def voice(self):
        return "неизвестный звук"

class Dog(Animal):
    def __init__(self, name, breed):
        super().__init__(name)
        self.breed = breed
    def voice(self):
        return "гав"

d = Dog("Шарик", "овчарка")
print(d.name, d.breed, d.voice())

class Animal:
    def voice(self):
        return "..."

class Dog(Animal):
    def voice(self):
        return "гав"

class Cat(Animal):
    def voice(self):
